import{_ as p,r as n,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Виджеты - October CMS - 3.x","titleTemplate":false,"description":"Самодостаточные блоки функциональности, решающие различные задачи.","frontmatter":{"subtitle":"Самодостаточные блоки функциональности, решающие различные задачи."},"headers":[{"level":2,"title":"Общие виджеты","slug":"общие-виджеты","link":"#общие-виджеты","children":[{"level":3,"title":"Определение класса","slug":"определение-класса","link":"#определение-класса","children":[]}]},{"level":2,"title":"Привязка виджетов к контроллерам","slug":"привязка-виджетов-к-контроллерам","link":"#привязка-виджетов-к-контроллерам","children":[]},{"level":2,"title":"Выполнение кода перед AJAX-обработчиками","slug":"выполнение-кода-перед-ajax-обработчиками","link":"#выполнение-кода-перед-ajax-обработчиками","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/extend/system/widgets.md","filePath":"3.x/ru/extend/system/widgets.md"}'),r={name:"3.x/ru/extend/system/widgets.md"};function u(k,s,d,g,h,m){const t=n("pre-heading"),e=n("post-heading");return o(),c("div",null,[a(t),s[0]||(s[0]=l("h1",null,"Виджеты",-1)),a(e),s[1]||(s[1]=i(`<p>Виджеты — это повторно используемые элементы управления, имеющие пользовательский интерфейс и контроллер панели управления (класс виджета), который подготавливает данные виджета и обрабатывает AJAX-запросы, генерируемые пользовательским интерфейсом виджета.</p><h2 id="общие-виджеты"><a href="#общие-виджеты" class="header-anchor">#</a> Общие виджеты</h2><p>Виджеты являются аналогом <a href="./../../cms/themes/components.html">CMS-компонентов</a> для панели управления. Они похожи тем, что представляют собой модульные блоки функциональности, предоставляют частичные представления и именуются с помощью псевдонимов. Ключевое отличие в том, что виджеты панели управления используют YAML-разметку для своей конфигурации и привязываются к контроллерам панели управления вручную.</p><p>Классы виджетов находятся в директории <strong>widgets</strong> директории плагина. Имя внутренней директории совпадает с именем класса виджета в нижнем регистре. Виджеты могут предоставлять ресурсы и частичные представления. Пример структуры директории виджета:</p><pre class="dir-container"><code><p>├── <code>widgets</code>
|   ├── form
|   |   ├── partials
|   |   |   └── _form.php  <em>← Файл частичного представления</em>
|   |   └── assets
|   |       ├── js
|   |       |   └── form.js  <em>← JavaScript-файл</em>
|   |       └── css
|   |           └── form.css  <em>← Файл стилей</em>
|   └── Form.php  <em>← Класс виджета</em></p>
</code></pre><h3 id="определение-класса"><a href="#определение-класса" class="header-anchor">#</a> Определение класса</h3><p>Классы общих виджетов должны наследовать класс <code>Backend\\Classes\\WidgetBase</code>. Как и любой другой класс плагина, контроллеры общих виджетов должны принадлежать <a href="./plugins.html">пространству имён плагина</a>. Ниже приведён пример определения класса виджета.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Backend<span class="token punctuation">\\</span>Widgets</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>WidgetBase</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Lists</span> <span class="token keyword">extends</span> <span class="token class-name">WidgetBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var string defaultAlias to identify this widget.
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$defaultAlias</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;list&#39;</span><span class="token punctuation">;</span>

    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Класс виджета должен содержать метод <strong>render()</strong> для формирования разметки виджета путём рендеринга частичного представления виджета. Пример:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;list&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Для передачи переменных в частичные представления вы можете добавить их в свойство <code>$vars</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;var&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;list&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Альтернативно вы можете передать переменные вторым параметром метода makePartial():</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;list&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;var&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="привязка-виджетов-к-контроллерам"><a href="#привязка-виджетов-к-контроллерам" class="header-anchor">#</a> Привязка виджетов к контроллерам</h2><div class="custom-block aside"><p>Привязка к контроллеру также необходима для того, чтобы сделать <a href="./ajax.html">AJAX-обработчики доступными</a>.</p></div><p>Виджет должен быть привязан к контроллеру панели управления, прежде чем вы сможете начать его использовать на странице или в частичном представлении панели управления. Используйте метод виджета <code>bindToController</code> для привязки к контроллеру. Лучшее место для инициализации виджета — метод контроллера <code>beforeDisplay</code>, который вызывается из конструктора.</p><p>Например, создание нового экземпляра виджета и привязка его к контроллеру. Обратите внимание, что конструктор принимает контроллер как первый аргумент.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeDisplay</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$myWidget</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">MyWidgetClass</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$myWidget</span><span class="token operator">-&gt;</span><span class="token property">alias</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;myWidget&#39;</span><span class="token punctuation">;</span>
    <span class="token variable">$myWidget</span><span class="token operator">-&gt;</span><span class="token function">bindToController</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>После привязки виджета вы можете обращаться к нему в представлении или частичном представлении контроллера по его псевдониму через свойство <code>$this-&gt;widget</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">widget</span><span class="token operator">-&gt;</span><span class="token property">myWidget</span><span class="token operator">-&gt;</span><span class="token function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="выполнение-кода-перед-ajax-обработчиками"><a href="#выполнение-кода-перед-ajax-обработчиками" class="header-anchor">#</a> Выполнение кода перед AJAX-обработчиками</h2><p>Иногда вам может потребоваться выполнить код перед запуском AJAX-обработчика. Определение метода <code>init</code> в виджете позволяет выполнять код перед каждым AJAX-обработчиком.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">init</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// From a widget class</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../forms/form-widgets.html">Виджеты форм</a></li><li><a href="./../lists/filter-widgets.html">Виджеты фильтров</a></li><li><a href="./../backend/report-widgets.html">Виджеты отчётов</a></li></ul></div>`,26))])}const y=p(r,[["render",u]]);export{v as __pageData,y as default};
